sys_script.script:
function onBefore(current, previous) {
    var states = current.getValue('visited_state') || '';
    var state_list = states.split(",");
    var present = false;

    var gr = new GlideRecord('sys_process_flow');
    gr.addEncodedQuery('table=rm_release^active=true');
    gr.orderBy('order');
    gr.query();
    var processFlowStatesOrder = {};
    while (gr.next()) {
        processFlowStatesOrder[gr.getValue('name')] = gr.getValue('order');
    }

    var stateListLength = state_list.length;

    while (stateListLength--) {

        if (state_list[stateListLength] == current.state) {
            present = true;
        }

        if (processFlowStatesOrder[state_list[stateListLength]] > processFlowStatesOrder[current.state]) {
            state_list.splice(stateListLength, 1);
        }
    }

    if (!present) {
        state_list.push(current.state);
    }
    current.visited_state = state_list.toString();
}
